class Solution {
public:
    int uniqueLetterString(string s) {
        int n = s.size();
        int last1[26], last2[26];
        for (int i = 0; i < 26; i++) {
            last1[i] = -1;
            last2[i] = -1;
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int c = s[i] - 'A';
            if (last1[c] != -1) {
                ans += (long long)(last1[c] - last2[c]) * (i - last1[c]);
            }
            last2[c] = last1[c];
            last1[c] = i;
        }
        for (int c = 0; c < 26; c++) {
            if (last1[c] != -1) {
                ans += (long long)(last1[c] - last2[c]) * (n - last1[c]);
            }
        }
        return (int)ans;
    }
};
